import math
import numpy as np
from scipy.optimize import least_squares


def _law(p, u, s, h):
    vmax, rho, tau_fast, amp_adapt, tau_slow = p
    drive = vmax * (1.0 - rho * s / (1.0 + s)) * u / (1.2 + u)
    return -drive * np.expm1(-h / tau_fast) + amp_adapt * u * np.expm1(-h / tau_slow)


def fit(train_rows):
    global _params
    u, s, h, y = np.array([[r['u_now'], r['s_grad'], r['H'], r['y']] for r in train_rows], dtype=float).T
    def residual(p):
        return _law(p, u, s, h) - y
    bounds = ([0.0, 0.0, 1e-5, 0.0, 1e-5], [np.inf, 1.0, np.inf, np.inf, np.inf])
    fits = [least_squares(residual, start, bounds=bounds, x_scale='jac', max_nfev=1000) for start in ([6.5, 0.7, 0.25, 1.5, 12.0], [8.0, 0.65, 0.5, 2.0, 25.0])]
    _params = min(fits, key=lambda result: result.cost).x


def predict(row):
    vmax, rho, tau_fast, amp_adapt, tau_slow = _params
    u, s, h = (float(row[k]) for k in ('u_now', 's_grad', 'H'))
    drive = vmax * (1.0 - rho * s / (1.0 + s)) * u / (1.2 + u)
    return float(-drive * math.expm1(-h / tau_fast) + amp_adapt * u * math.expm1(-h / tau_slow))
